\caption{Weight update algorithm}\KwData{$\Delta w_{j,i} 
eq 0$, $w^{OLD}_{j,i}$}\KwResult{new $g^{+}_{j,i}$, new $g^{-}_{j,i}$}\Comment{Evaluate new weight value:}$w^{NEW}_{j,i} \gets w^{OLD}_{j,i} - \Delta w_{j,i}$ \;\If{$g^{+}_{j,i} 
eq G^+_{min}$} {$g^{+}_{j,i} \gets G^+_{min} $ \Comment*[r]{reset $g^{+}_{j,i}$}}\If{$g^{-}_{j,i} 
eq G^-_{min}$} {$g^{-}_{j,i} \gets G^-_{min}$ \Comment*[r]{reset $g^{-}_{j,i}$}}\Comment{Program synaptic devices:}\If{$w^{NEW}_{j,i} 
eq 0$}{\Comment{Evaluate number of input pulses:}$P_{j,i} \gets 
int{P^{LTP}_{j,i}}$\Comment{Set value for $g^{+}_{j,i}$ or $g^{-}_{j,i}$:}\eIf{$w^{NEW}_{j,i} > 0$} {$g^{+}_{j,i} \gets  rac{G^+_{max}-G^+_{min}}{1-e^{- rac{P_{max}}{\alpha_{LTP}}}} \left(1-e^{- rac{P_{j,i}}{\alpha_{LTP}}}ight) + G^+_{min} $}{$g^{-}_{j,i} \gets  rac{G^-_{max}-G^-_{min}}{1-e^{- rac{P_{max}}{\alpha_{LTP}}}} \left(1-e^{- rac{P_{j,i}}{\alpha_{LTP}}}ight) + G^-_{min} $}}
